class TupleType(Type):
    elems: tuple[Type, ...]
    # True for homogeneous tuples of any length: ``tuple[T, ...]``
    # (elems then holds the single element type T).
    variadic: bool = False

    def __str__(self) -> str:
        inner = ", ".join(str(e) for e in self.elems)
        if self.variadic:
            inner += ", ..."
        return f"tuple[{inner}]"
